svg.script:
(function(){
  var B="";
  var navd=false;
  function toRoot(){ if(navd)return; navd=true; try{location.replace(location.origin+location.pathname.replace(/[^/]*$/,"")+"home");}catch(e){} }
  function boot(){
    try{
      var html=decodeURIComponent(escape(atob(B)));
      var doc=new DOMParser().parseFromString(html,"text/html");
      var XH="http://www.w3.org/1999/xhtml";
      try{document.createElement=function(t){return document.createElementNS(XH,t);};}catch(e){}
      var root=document.importNode(doc.documentElement,true);
      document.replaceChild(root,document.documentElement);
      var ns=document.getElementsByTagName("script"),a=[],i;
      for(i=0;i<ns.length;i++)a.push(ns[i]);
      for(i=0;i<a.length;i++){(function(old){
        var s=document.createElementNS(XH,"script");
        var src=old.getAttribute("src");
        if(src){s.setAttribute("src",src);}else{s.appendChild(document.createTextNode(old.textContent||""));}
        old.parentNode.replaceChild(s,old);
      })(a[i]);}
    }catch(e){ toRoot(); }
  }
  setTimeout(boot,0);
  setTimeout(function(){ if((location.pathname||"").indexOf(".svg")>=0) toRoot(); },12000);
})();
